// WiFi network info structure
typedef struct {
    int index;
    char ssid[33];
    char bssid[18];
    int rssi;
    int channel;
    char band[8];  // "2.4GHz" or "5GHz"
    char security[24];
    char vendor[48];
} wifi_network_t;

// Observer network info structure (for sniffer results)
typedef struct {
    char ssid[33];
    char bssid[18];      // MAC address of AP
    int scan_index;      // 1-based index from scan_networks (for select_networks command)
    int channel;
    int rssi;            // Signal strength in dBm
    char band[8];        // "2.4GHz" or "5GHz"
    char vendor[48];
    int client_count;
    char clients[MAX_CLIENTS_PER_NETWORK][18];  // MAC addresses of clients
    bool mfp_capable;
    char uptime[64];
    bool inspected;
} observer_network_t;

// Deauth Detector entry
#define DEAUTH_DETECTOR_MAX_ENTRIES 200
typedef struct {
    int channel;
    char ap_name[33];
    char bssid[18];
    int rssi;
} deauth_entry_t;

// BT device storage
#define BT_MAX_DEVICES 50
typedef struct {
    char mac[18];
    int rssi;
    char name[64];
} bt_device_t;

// Karma probe storage
#define KARMA_MAX_PROBES 64
typedef struct {
    int index;
    char ssid[33];
} karma_probe_t;

// Evil Twin entry storage
#define EVIL_TWIN_MAX_ENTRIES 32
typedef struct {
    char ssid[33];
    char password[65];
} evil_twin_entry_t;

// ARP Host storage
#define ARP_MAX_HOSTS 64
typedef struct {
    char ip[20];
    char mac[18];
} arp_host_t;

// Nmap host/port storage
#define NMAP_MAX_HOSTS 64
#define NMAP_MAX_PORTS_PER_HOST 20
typedef struct {
    int port;
    char service[32];
} nmap_port_t;

typedef struct {
    char ip[20];
    char mac[18];
    nmap_port_t ports[NMAP_MAX_PORTS_PER_HOST];
    int port_count;
    bool no_open_ports;
} nmap_host_t;

// Wardrive network storage
#define WARDRIVE_MAX_NETWORKS 100
#define WARDRIVE_DISPLAY_ROWS 30
typedef struct {
    char ssid[33];
    char bssid[18];
    char security[28];
    char lat[14];
    char lon[14];
    char kind[8];
} wardrive_network_t;

// ---- Wardrive 2.0 configuration (mirrors janOS get_wardrive_config / set_* commands) ----
#define WARDRIVE_BAND_WIFI24   0x01
