    lv_obj_set_style_bg_color(yes_btn, COLOR_MATERIAL_RED, 0);
    lv_obj_set_style_radius(yes_btn, 8, 0);
    lv_obj_add_event_cb(yes_btn, blackout_confirm_yes_cb, LV_EVENT_CLICKED, ctx);

