        snprintf(cmd, sizeof(cmd), "wdgwars_upload %s", file->name);
        transport_write_bytes_tab(active_tab, uart_port, cmd, strlen(cmd));
        transport_write_bytes_tab(active_tab, uart_port, "\r\n", 2);
