    lv_label_set_text(title, LV_SYMBOL_WIFI " Karma Attack Active");
    lv_obj_set_style_text_font(title, &lv_font_montserrat_22, 0);
    lv_obj_set_style_text_color(title, COLOR_MATERIAL_ORANGE, 0);

